        {"id": "q15", "skill": "reading", "type": "multiple_choice", "passageTitle": "Avertissement", "passageContent": "RUE FERMÉE\n\nPour travaux\n\nDu 10 au 20 juin\n\nPrendre rue alternate", "instruction": "Quand finit les travaux?", "options": ["Le 9 juin", "Le 20 juin", "Le 30 juin", "Le 10 juillet"], "correctAnswer": "Le 20 juin", "points": 1},
