        {"id": "q5", "skill": "reading", "type": "multiple_choice", "passageTitle": "Annonce", "passageContent": "VENTE VOITURE\n\nPeugeot 207\n\nAnnée: 2018\n\n50 000 km\n\nPrix: 8 000€", "instruction": "Quel est l'année de la voiture?", "options": ["2016", "2017", "2018", "2019"], "correctAnswer": "2018", "points": 1},
        {"id": "q6", "skill": "reading", "type": "multiple_choice", "passageTitle": "Avertissement", "passageContent": "RAPPEL\n\nPaiement loyer\n\nDate limite: 28 du mois\n\nMerci de respecter l'échéance", "instruction": "Quand payer le loyer?", "options": ["Début du mois", "Fin du mois", "Milieu du mois", "N'importe quand"], "correctAnswer": "Fin du mois", "points": 1},
        {"id": "q7", "skill": "reading", "type": "true_false", "passageTitle": "Email", "passageContent": "Objet: Confirmation RDV\n\nBonjour,\n\nNous avons bien reçu votre demande.\n\nNous vous contactons demain.\n\nCordialement", "instruction": "On répond aujourd'hui.", "correctAnswer": "false", "points": 1},
        {"id": "q8", "skill": "reading", "type": "multiple_choice", "passageTitle": "Menu", "passageContent": "CAFÉ DE LA PLACE\n\nCafé: 2.50€\nThé: 2.50€\nChocolat: 3€\nJus d'orange: 3.50€\n\nCroissant: 1.50€", "instruction": "Le moins coûteux?", "options": ["Café", "Thé", "Croissant", "Chocolat"], "correctAnswer": "Croissant", "points": 1},
        {"id": "q9", "skill": "reading", "type": "multiple_choice", "passageTitle": "Avertissement", "passageContent": "INTERDIT AUX CHIENS\n\nSauf guide", "instruction": "Les petits chiens sont autorisés.", "options": ["Oui", "Non", "Only", "Tous"], "correctAnswer": "Non", "points": 1},
        {"id": "q10", "skill": "reading", "type": "true_false", "passageTitle": "Prospectus", "passageContent": "SOLDE SPECIAL\n\nChemise: 20€ au lieu de 40€\nPantalon: 30€ au lieu de 60€", "instruction": "La chemise coûte 40€.", "correctAnswer": "false", "points": 1},
        {"id": "q11", "skill": "reading", "type": "multiple_choice", "passageTitle": "Ticket", "passageContent": "BILLET DE TRAIN\n\nParis - Bordeaux\n\nDépart: 14h50\n\nVoiture: 8\nPlace: 45", "instruction": "A quelle heure le départ?", "options": ["14h00", "14h30", "14h50", "15h00"], "correctAnswer": "14h50", "points": 1},
