        {"id": "q15", "skill": "listening", "type": "multiple_choice", "content": "Interview: Pourquoi ce métier? J'ai toujours voulu aider les gens. C'est pour ça que je suis infirmière depuis vingt ans.", "instruction": "Métier?", "options": ["Médecin", "Infirmière", "Avocat", "Professeur"], "correctAnswer": "Infirmière", "points": 1, "audioUrl": "/assets/audio/delf-a2-full-3/q15.mp3"},
