        {"id": "q20", "skill": "listening", "type": "multiple_choice", "content": "Emission culturelle: Nous parlons de la littérature française du dix-neuvième siècle. Les grands auteurs comme Hugo seront analysés.", "instruction": "Période?", "options": ["18ème siècle", "19ème siècle", "20ème siècle", "21ème siècle"], "correctAnswer": "19ème siècle", "points": 1, "audioUrl": "/assets/audio/delf-a2-full-3/q20.mp3"},
