        {"id": "q14", "skill": "listening", "type": "multiple_choice", "content": "Interview: Pourquoi ce métier? J'ai toujours voulu aider les gens. Je suis infirmière.", "instruction": "Métier?", "options": ["Médecin", "Infirmière", "Avocat", "Professeur"], "correctAnswer": "Infirmière", "points": 1, "audioUrl": "/assets/audio/delf-a2-full-6/q14.mp3"},
        {"id": "q15", "skill": "listening", "type": "multiple_choice", "content": "Actualités: Le président a annoncé de nouvelles mesures pour protéger l'environnement.", "instruction": "Sujet?", "options": ["L'économie", "L'éducation", "L'environnement", "La santé"], "correctAnswer": "L'environnement", "points": 1, "audioUrl": "/assets/audio/delf-a2-full-6/q15.mp3"},
