        {"id": "q17", "skill": "listening", "type": "multiple_choice", "content": "Rapport: Le nombre de chômeurs a augmenté cette année. L'industrie est le secteur le plus touché.", "instruction": "Secteur?", "options": ["Les services", "L'industrie", "L'agriculture", "Le tourisme"], "correctAnswer": "L'industrie", "points": 1, "audioUrl": "/assets/audio/delf-a2-full-6/q17.mp3"},
